import sys
import hashlib
import os
import time

def compute_digest(password: str, salt: bytes) -> str:
    return hashlib.sha256(salt + password.encode('utf-8')).hexdigest()

def generate_signature(token_part: str, secret_key: bytes) -> str:
    return hashlib.sha256(secret_key + token_part.encode('utf-8')).hexdigest()

def main():
    username = sys.stdin.readline().strip()
    password = sys.stdin.readline().strip()

    try:
        with open('users.txt', 'r') as file:
            for line in file:
                parts = line.strip().split(':')
                if len(parts) != 3:
                    continue
                stored_username, stored_salt, stored_digest = parts
                if stored_username == username:
                    salt = bytes.fromhex(stored_salt)
                    computed_digest = compute_digest(password, salt)
                    if computed_digest == stored_digest:
                        break
            else:
                print("ACCESS_DENIED")
                sys.exit(1)

        with open('secret.key', 'r') as file:
            secret_key = file.read().strip().encode('utf-8')

        expiry = int(time.time()) + 3600
        token_part = f"{username}:{expiry}"
        signature = generate_signature(token_part, secret_key)

        token = f"{username}:{expiry}:{signature}"
        with open('token.txt', 'w') as file:
            file.write(token)

        print("OK")
        sys.exit(0)
    except FileNotFoundError:
        print("ACCESS_DENIED")
        sys.exit(1)

if __name__ == "__main__":
    main()

