    token = token.strip()
    username = username.strip()
    password = password.strip()
    cred_path = cred_path.strip()

    with open(cred_path, 'r') as cred_file:
        for line in cred_file:
            cred_username, cred_digest = line.strip().split(':', 1)
            if cred_username == username:
                computed_digest = transform_password(password)
                if computed_digest == cred_digest:
                    signature = transform_signature(username, password)
                    with open(token, 'w') as out_file:
                        out_file.write(f"{username}:{signature}")
                    print(f"{username}:{signature}")
                    sys.exit(0)

    print("ACCESS_DENIED")
    sys.exit(1)

if __name__ == "__main__":
